param([ValidateSet('x86','x64')][string]$Platform = 'x86')
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
$source = Join-Path $repoRoot '.deps/dxvk-remix'
. (Join-Path $source 'bridge/build_common.ps1')
SetupVS -Platform $Platform -VcVarsVer '14.29'
$output = Join-Path $repoRoot ".deps/binding-references-$Platform"
New-Item -ItemType Directory -Force $output | Out-Null
& python "$repoRoot/scripts/prepare_binding_reference_test.py" --source $source --output $output
if ($LASTEXITCODE -ne 0) { throw 'Binding ownership source generation failed' }
Push-Location $output
try {
  & cl.exe /nologo /std:c++17 /EHsc /W4 /WX /DNOMINMAX /O2 /MT "/I$repoRoot/tests" "/I$output" actual_binding_references.cpp /Fe:binding-references.exe
  if ($LASTEXITCODE -ne 0) { throw 'Binding ownership compilation failed' }
  & .\binding-references.exe
  if ($LASTEXITCODE -ne 0) { throw 'Binding ownership regression test failed' }
} finally { Pop-Location }
